package Server.TCP;

import java.io.Serializable;
import java.util.Arrays;
import java.util.UUID;

/**
 * Generic serializable RPC message envelope for TCP socket communication.
 * Encapsulates the call identifier, method name, parameter types, and arguments.
 */
public class TCPMessage implements Serializable
{
	private static final long serialVersionUID = 1L;

	private String m_id;
	private String m_methodName;
	private Class<?>[] m_paramTypes;
	private Object[] m_args;

	public TCPMessage()
	{
		this.m_id = UUID.randomUUID().toString();
	}

	public TCPMessage(String methodName, Class<?>[] paramTypes, Object[] args)
	{
		this.m_id = UUID.randomUUID().toString();
		this.m_methodName = methodName;
		this.m_paramTypes = paramTypes;
		this.m_args = args;
	}

	public TCPMessage(String id, String methodName, Class<?>[] paramTypes, Object[] args)
	{
		this.m_id = id;
		this.m_methodName = methodName;
		this.m_paramTypes = paramTypes;
		this.m_args = args;
	}

	public String getId()
	{
		return m_id;
	}

	public void setId(String id)
	{
		this.m_id = id;
	}

	public String getMethodName()
	{
		return m_methodName;
	}

	public void setMethodName(String methodName)
	{
		this.m_methodName = methodName;
	}

	public Class<?>[] getParamTypes()
	{
		return m_paramTypes;
	}

	public void setParamTypes(Class<?>[] paramTypes)
	{
		this.m_paramTypes = paramTypes;
	}

	public Object[] getArgs()
	{
		return m_args;
	}

	public void setArgs(Object[] args)
	{
		this.m_args = args;
	}

	@Override
	public String toString()
	{
		return "TCPMessage[id=" + m_id + ", method=" + m_methodName + 
			", args=" + (m_args == null ? "[]" : Arrays.toString(m_args)) + "]";
	}
}

package Server.TCP;

import java.io.Serializable;

/**
 * Generic serializable RPC response envelope for TCP socket communication.
 * Encapsulates the call identifier, return object value, or remote exception.
 */
public class TCPResponse implements Serializable
{
	private static final long serialVersionUID = 1L;

	private String m_id;
	private Object m_result;
	private Exception m_exception;

	public TCPResponse()
	{
	}

	public TCPResponse(String id, Object result)
	{
		this.m_id = id;
		this.m_result = result;
		this.m_exception = null;
	}

	public TCPResponse(String id, Object result, Exception exception)
	{
		this.m_id = id;
		this.m_result = result;
		this.m_exception = exception;
	}

	public String getId()
	{
		return m_id;
	}

	public void setId(String id)
	{
		this.m_id = id;
	}

	public Object getResult()
	{
		return m_result;
	}

	public void setResult(Object result)
	{
		this.m_result = result;
	}

	public Exception getException()
	{
		return m_exception;
	}

	public void setException(Exception exception)
	{
		this.m_exception = exception;
	}

	public boolean isSuccess()
	{
		return m_exception == null;
	}

	public Object unwrap() throws Exception
	{
		if (m_exception != null)
		{
			throw m_exception;
		}
		return m_result;
	}

	@Override
	public String toString()
	{
		if (m_exception != null)
		{
			return "TCPResponse[id=" + m_id + ", error=" + m_exception.getMessage() + "]";
		}
		return "TCPResponse[id=" + m_id + ", result=" + m_result + "]";
	}
}

package Server.TCP;

import java.io.*;
import java.net.Socket;
import java.rmi.RemoteException;

/**
 * Dynamic Client RPC Proxy for TCP socket communication.
 * Marshals arbitrary interface invocations into generic request envelopes (TCPMessage)
 * and transparently unwraps server replies (TCPResponse).
 */
public class TCPProxy implements java.lang.reflect.InvocationHandler, Serializable
{
	private static final long serialVersionUID = 1L;

	private String m_host;
	private int m_port;

	public TCPProxy(String host, int port)
	{
		this.m_host = host;
		this.m_port = port;
	}

	public String getHost()
	{
		return m_host;
	}

	public int getPort()
	{
		return m_port;
	}

	/**
	 * Factory method generating a dynamic proxy instance implementing the target interface.
	 */
	@SuppressWarnings("unchecked")
	public static <T> T create(String host, int port, Class<T> interfaceClass)
	{
		return (T) java.lang.reflect.Proxy.newProxyInstance(
			interfaceClass.getClassLoader(),
			new Class<?>[]{interfaceClass},
			new TCPProxy(host, port)
		);
	}

	@Override
	public Object invoke(Object proxy, java.lang.reflect.Method method, Object[] args) throws Throwable
	{
		// Intercept standard Object methods locally
		String name = method.getName();
		if (name.equals("hashCode")) {
			return System.identityHashCode(proxy);
		}
		if (name.equals("equals")) {
			return proxy == args[0];
		}
		if (name.equals("toString")) {
			return "TCPProxy[" + m_host + ":" + m_port + "]";
		}

		// Encapsulate call into generic RPC message envelope
		TCPMessage message = new TCPMessage(name, method.getParameterTypes(), args);

		// Connect to remote TCP endpoint and execute synchronous request-response
		try (Socket socket = new Socket(m_host, m_port))
		{
			socket.setTcpNoDelay(true);

			ObjectOutputStream oos = new ObjectOutputStream(socket.getOutputStream());
			oos.flush();
			oos.writeObject(message);
			oos.flush();

			ObjectInputStream ois = new ObjectInputStream(socket.getInputStream());
			Object responseObj = ois.readObject();

			if (responseObj instanceof TCPResponse)
			{
				TCPResponse response = (TCPResponse) responseObj;
				return response.unwrap();
			}
			else
			{
				throw new RemoteException("Unexpected RPC response object type: " + 
					(responseObj == null ? "null" : responseObj.getClass().getName()));
			}
		}
		catch (Exception e)
		{
			// If the underlying method declares this exception type, rethrow directly
			for (Class<?> declaredException : method.getExceptionTypes())
			{
				if (declaredException.isInstance(e))
				{
					throw e;
				}
			}
			// Otherwise wrap in standard RemoteException
			throw new RemoteException("TCP RPC invocation failed for '" + name + "' on " + m_host + ":" + m_port, e);
		}
	}
}

package Client;

import Server.Interface.*;
import Server.TCP.TCPProxy;

import java.io.*;
import java.util.*;
import java.rmi.RemoteException;

/**
 * TCP Socket Client for COMP 512 Travel Reservation Information System.
 * Connects to the TCP Middleware using dynamic reflection proxies and executes CLI commands.
 */
public class TCPClient extends Client
{
	private static String s_serverHost = "localhost";
	private static int s_serverPort = 3021;

	public static void main(String args[])
	{
		if (args.length > 0)
		{
			s_serverHost = args[0];
		}
		if (args.length > 1)
		{
			try {
				s_serverPort = Integer.parseInt(args[1]);
			} catch (NumberFormatException e) {
				System.err.println("Invalid port number: " + args[1]);
				System.exit(1);
			}
		}
		if (args.length > 2)
		{
			System.err.println("Usage: java Client.TCPClient [server_hostname [server_port]]");
			System.exit(1);
		}

		try {
			TCPClient client = new TCPClient();
			client.connectServer();
			client.start();
		}
		catch (Exception e) {
			System.err.println("Client exception: Uncaught exception");
			e.printStackTrace();
			System.exit(1);
		}
	}

	public TCPClient()
	{
		super();
	}

	@Override
	public void connectServer()
	{
		connectServer(s_serverHost, s_serverPort);
	}

	public void connectServer(String host, int port)
	{
		boolean first = true;
		while (true)
		{
			try {
				IResourceManager proxy = TCPProxy.create(host, port, IResourceManager.class);
				// Probe the server to verify connectivity
				String name = proxy.getName();
				m_resourceManager = proxy;
				System.out.println("Connected to '" + name + "' TCP server [" + host + ":" + port + "]");
				break;
			}
			catch (Exception e) {
				if (first) {
					System.out.println("Waiting for TCP server [" + host + ":" + port + "]...");
					first = false;
				}
				try {
					Thread.sleep(500);
				} catch (InterruptedException ie) {
					Thread.currentThread().interrupt();
					break;
				}
			}
		}
	}
}

package Server.TCP;

import Server.Common.*;
import Server.Interface.*;

import java.io.*;
import java.net.ServerSocket;
import java.net.Socket;
import java.net.SocketException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

/**
 * Multi-threaded TCP Backend Server for ResourceManagers (Flights, Cars, Rooms).
 * Listens on a dedicated TCP port, dispatches concurrent requests across an
 * executor thread pool, and executes operations on the underlying ResourceManager.
 */
public class TCPResourceManager
{
	private String m_name;
	private int m_port;
	private ResourceManager m_rm;
	private ServerSocket m_serverSocket;
	private ExecutorService m_threadPool;
	private volatile boolean m_running = true;

	public TCPResourceManager(String name, int port)
	{
		this.m_name = name;
		this.m_port = port;
		this.m_rm = new ResourceManager(name);
		this.m_threadPool = Executors.newCachedThreadPool();
	}

	public void start()
	{
		try {
			m_serverSocket = new ServerSocket(m_port);
			Trace.info("TCPResourceManager['" + m_name + "'] listening on port " + m_port);
			System.out.println("'" + m_name + "' TCP resource manager server ready on port " + m_port);

			// Register shutdown hook for graceful termination
			Runtime.getRuntime().addShutdownHook(new Thread() {
				@Override
				public void run() {
					stop();
				}
			});

			while (m_running)
			{
				try {
					Socket clientSocket = m_serverSocket.accept();
					clientSocket.setTcpNoDelay(true);
					m_threadPool.execute(new RequestHandler(clientSocket));
				}
				catch (SocketException se) {
					if (!m_running) {
						break;
					}
					Trace.warn("SocketException in TCPResourceManager accept: " + se.getMessage());
				}
			}
		}
		catch (IOException e) {
			if (m_running) {
				System.err.println("TCPResourceManager server error: " + e.getMessage());
				e.printStackTrace();
			}
		}
		finally {
			stop();
		}
	}

	public void stop()
	{
		m_running = false;
		try {
			if (m_serverSocket != null && !m_serverSocket.isClosed()) {
				m_serverSocket.close();
			}
		} catch (IOException ignored) {}

		if (m_threadPool != null && !m_threadPool.isShutdown()) {
			m_threadPool.shutdown();
			try {
				if (!m_threadPool.awaitTermination(3, TimeUnit.SECONDS)) {
					m_threadPool.shutdownNow();
				}
			} catch (InterruptedException e) {
				m_threadPool.shutdownNow();
			}
		}
		System.out.println("'" + m_name + "' TCP server stopped cleanly");
	}

	/**
	 * Worker task handling an individual client/middleware TCP connection.
	 */
	private class RequestHandler implements Runnable
	{
		private Socket m_socket;

		public RequestHandler(Socket socket)
		{
			this.m_socket = socket;
		}

		@Override
		public void run()
		{
			try (
				ObjectInputStream ois = new ObjectInputStream(m_socket.getInputStream());
				ObjectOutputStream oos = new ObjectOutputStream(m_socket.getOutputStream())
			) {
				oos.flush();
				Object inputObj = ois.readObject();

				if (inputObj instanceof TCPMessage)
				{
					TCPMessage message = (TCPMessage) inputObj;
					TCPResponse response = dispatch(message);
					oos.writeObject(response);
					oos.flush();
				}
				else
				{
					Trace.warn("TCPResourceManager received unexpected message: " + inputObj);
				}
			}
			catch (EOFException ignored) {
				// Client closed connection cleanly
			}
			catch (Exception e) {
				Trace.warn("Error handling TCP request on " + m_name + ": " + e.getMessage());
			}
			finally {
				try {
					if (m_socket != null && !m_socket.isClosed()) {
						m_socket.close();
					}
				} catch (IOException ignored) {}
			}
		}

		private TCPResponse dispatch(TCPMessage msg)
		{
			String methodName = msg.getMethodName();
			Class<?>[] paramTypes = msg.getParamTypes();
			Object[] args = msg.getArgs();

			try {
				java.lang.reflect.Method method = m_rm.getClass().getMethod(methodName, paramTypes);
				Object result = method.invoke(m_rm, args);
				return new TCPResponse(msg.getId(), result);
			}
			catch (java.lang.reflect.InvocationTargetException ite) {
				Throwable cause = ite.getCause();
				Exception ex = (cause instanceof Exception) ? (Exception) cause : new Exception(cause);
				return new TCPResponse(msg.getId(), null, ex);
			}
			catch (Exception e) {
				return new TCPResponse(msg.getId(), null, e);
			}
		}
	}

	public static void main(String[] args)
	{
		String serverName = "Server";
		int port = 3022;

		if (args.length > 0) {
			serverName = args[0];
		}
		if (args.length > 1) {
			try {
				port = Integer.parseInt(args[1]);
			} catch (NumberFormatException e) {
				System.err.println("Invalid port number: " + args[1]);
				System.exit(1);
			}
		}

		TCPResourceManager server = new TCPResourceManager(serverName, port);
		server.start();
	}
}

package Server.TCP;

import Server.Common.*;
