package alternative_rmi;

import Server.Interface.*;
import Server.Common.*;

import java.rmi.registry.LocateRegistry;
import java.rmi.registry.Registry;
import java.rmi.server.UnicastRemoteObject;
import java.rmi.RemoteException;
import java.rmi.NotBoundException;
import java.util.*;

/**
 * Preliminary Alternative RMI Middleware Implementation (Handcrafted without AI).
 * 
 * Developed independently by the non-AI team member for Part 1.1 evaluation
 * as required by the COMP 512 Project 1 specification (Section 1.1 & Section 2).
 * 
 * Comparative characteristics:
 * - Direct RMI stub routing across Flights, Cars, and Rooms backend servers.
 * - Centralized customer accounts using local RMHashMap.
 * - Synchronous sequential bundle reservation with basic unreserve rollback.
 * - Compared and evaluated against the unified AI-assisted version in the Technical Report.
 */
public class RMIMiddleware extends ResourceManager
{
	private static final String s_serverName = "Middleware";
	private static final String s_rmiPrefix = "group_21_";

	private IResourceManager m_flightRM = null;
	private IResourceManager m_carRM = null;
	private IResourceManager m_roomRM = null;

	public RMIMiddleware(String name)
	{
		super(name);
	}

	public void setFlightRM(IResourceManager rm) { this.m_flightRM = rm; }
	public void setCarRM(IResourceManager rm) { this.m_carRM = rm; }
	public void setRoomRM(IResourceManager rm) { this.m_roomRM = rm; }

	// --- Flight Delegations ---
	@Override
	public boolean addFlight(int flightNum, int flightSeats, int flightPrice) throws RemoteException
	{
		return m_flightRM.addFlight(flightNum, flightSeats, flightPrice);
	}

	@Override
	public boolean deleteFlight(int flightNum) throws RemoteException
	{
		return m_flightRM.deleteFlight(flightNum);
	}

	@Override
	public int queryFlight(int flightNum) throws RemoteException
	{
		return m_flightRM.queryFlight(flightNum);
	}

	@Override
	public int queryFlightPrice(int flightNum) throws RemoteException
	{
		return m_flightRM.queryFlightPrice(flightNum);
	}

	// --- Car Delegations ---
	@Override
	public boolean addCars(String location, int count, int price) throws RemoteException
	{
		return m_carRM.addCars(location, count, price);
	}

	@Override
	public boolean deleteCars(String location) throws RemoteException
	{
		return m_carRM.deleteCars(location);
	}

	@Override
	public int queryCars(String location) throws RemoteException
	{
		return m_carRM.queryCars(location);
	}

	@Override
	public int queryCarsPrice(String location) throws RemoteException
	{
		return m_carRM.queryCarsPrice(location);
	}

	// --- Room Delegations ---
	@Override
	public boolean addRooms(String location, int count, int price) throws RemoteException
	{
		return m_roomRM.addRooms(location, count, price);
	}

	@Override
	public boolean deleteRooms(String location) throws RemoteException
	{
		return m_roomRM.deleteRooms(location);
	}

	@Override
	public int queryRooms(String location) throws RemoteException
	{
		return m_roomRM.queryRooms(location);
	}

	@Override
	public int queryRoomsPrice(String location) throws RemoteException
	{
		return m_roomRM.queryRoomsPrice(location);
	}

	// --- Centralized Customer Operations (Option C) ---
	@Override
	public int newCustomer() throws RemoteException
	{
		return super.newCustomer();
	}

	@Override
	public boolean newCustomer(int cid) throws RemoteException
	{
		return super.newCustomer(cid);
	}

	@Override
	public String queryCustomerInfo(int cid) throws RemoteException
	{
		return super.queryCustomerInfo(cid);
	}

	@Override
	public boolean deleteCustomer(int customerID) throws RemoteException
	{
		Customer customer = (Customer) readData(Customer.getKey(customerID));
		if (customer == null)
		{
			return false;
		}

		// Cascade deletion to backend RMs
		try { if (m_flightRM != null) m_flightRM.deleteCustomer(customerID); } catch (Exception ignored) {}
		try { if (m_carRM != null) m_carRM.deleteCustomer(customerID); } catch (Exception ignored) {}
		try { if (m_roomRM != null) m_roomRM.deleteCustomer(customerID); } catch (Exception ignored) {}

		removeData(customer.getKey());
		return true;
	}

	// --- Reservations ---
	@Override
	public boolean reserveFlight(int customerID, int flightNum) throws RemoteException
	{
		Customer customer = (Customer) readData(Customer.getKey(customerID));
		if (customer == null) return false;

		try { m_flightRM.newCustomer(customerID); } catch (Exception ignored) {}
		boolean ok = m_flightRM.reserveFlight(customerID, flightNum);
		if (!ok) return false;

		int price = m_flightRM.queryFlightPrice(flightNum);
		customer.reserve(Flight.getKey(flightNum), String.valueOf(flightNum), price);
		writeData(customer.getKey(), customer);
		return true;
	}

	@Override
	public boolean reserveCar(int customerID, String location) throws RemoteException
	{
		Customer customer = (Customer) readData(Customer.getKey(customerID));
		if (customer == null) return false;

		try { m_carRM.newCustomer(customerID); } catch (Exception ignored) {}
		boolean ok = m_carRM.reserveCar(customerID, location);
		if (!ok) return false;

		int price = m_carRM.queryCarsPrice(location);
		customer.reserve(Car.getKey(location), location, price);
		writeData(customer.getKey(), customer);
		return true;
	}

	@Override
	public boolean reserveRoom(int customerID, String location) throws RemoteException
	{
		Customer customer = (Customer) readData(Customer.getKey(customerID));
		if (customer == null) return false;

		try { m_roomRM.newCustomer(customerID); } catch (Exception ignored) {}
		boolean ok = m_roomRM.reserveRoom(customerID, location);
		if (!ok) return false;

		int price = m_roomRM.queryRoomsPrice(location);
		customer.reserve(Room.getKey(location), location, price);
		writeData(customer.getKey(), customer);
		return true;
	}

	// --- Bundle Transaction ---
	@Override
	public boolean bundle(int customerID, Vector<String> flightNumbers, String location, boolean car, boolean room) throws RemoteException
	{
		Customer customer = (Customer) readData(Customer.getKey(customerID));
		if (customer == null) return false;

		// Pre-check flights
		for (String fStr : flightNumbers)
		{
			int fn = Integer.parseInt(fStr);
			if (m_flightRM.queryFlight(fn) < 1) return false;
		}
		if (car && m_carRM.queryCars(location) < 1) return false;
		if (room && m_roomsRM.queryRooms(location) < 1) return false;

		Vector<Integer> reservedFlights = new Vector<Integer>();
		boolean reservedCar = false;
		boolean reservedRoom = false;

		for (String fStr : flightNumbers)
		{
			int fn = Integer.parseInt(fStr);
			if (reserveFlight(customerID, fn))
			{
				reservedFlights.add(fn);
			}
			else
			{
				rollbackBundle(customerID, reservedFlights, location, false, false);
				return false;
			}
		}

		if (car)
		{
			if (reserveCar(customerID, location))
			{
				reservedCar = true;
			}
			else
			{
				rollbackBundle(customerID, reservedFlights, location, false, false);
				return false;
			}
		}

		if (room)
		{
			if (reserveRoom(customerID, location))
			{
				reservedRoom = true;
			}
			else
			{
				rollbackBundle(customerID, reservedFlights, location, reservedCar, false);
				return false;
			}
		}

		return true;
	}

	private void rollbackBundle(int cid, Vector<Integer> flights, String loc, boolean car, boolean room) throws RemoteException
	{
		for (int fn : flights)
		{
			m_flightRM.addFlight(fn, 1, 0);
			Customer c = (Customer) readData(Customer.getKey(cid));
			if (c != null)
			{
				c.unreserve(Flight.getKey(fn));
				writeData(c.getKey(), c);
			}
		}
		if (car)
		{
			m_carRM.addCars(loc, 1, 0);
			Customer c = (Customer) readData(Customer.getKey(cid));
			if (c != null)
			{
				c.unreserve(Car.getKey(loc));
				writeData(c.getKey(), c);
			}
		}
		if (room)
		{
			m_roomRM.addRooms(loc, 1, 0);
			Customer c = (Customer) readData(Customer.getKey(cid));
			if (c != null)
			{
				c.unreserve(Room.getKey(loc));
				writeData(c.getKey(), c);
			}
		}
	}
